import { APPS, CATALOG_VERSION } from "./catalog.js";

const DEFAULT_REPO = "https://github.com/peytonmscott/macbook-setup.git";

/**
 * @param {object} config
 * @param {{ repoUrl?: string }} [opts]
 */
export function generateSetupScript(config, opts = {}) {
  const repoUrl = opts.repoUrl || DEFAULT_REPO;
  const json = JSON.stringify(config, null, 2);

  return `#!/usr/bin/env bash
# Generated by macbook-setup web configurator
# Inspect this file before running. Idempotent where possible.
set -euo pipefail

REPO_URL="${repoUrl}"
INSTALL_DIR="\${INSTALL_DIR:-\$HOME/Developer/macbook-setup}"
CONFIG_PATH="\${CONFIG_PATH:-\$HOME/Developer/macbook-setup.machine.json}"

echo "================================"
echo "  macbook-setup"
echo "  Generated machine provisioner"
echo "================================"
echo

if [[ "\$(uname -s)" != "Darwin" ]]; then
  echo "This script only supports macOS." >&2
  exit 1
fi

mkdir -p "\${CONFIG_PATH%/*}"
cat > "\$CONFIG_PATH" <<'MACBOOK_SETUP_JSON'
${json}
MACBOOK_SETUP_JSON

echo "Wrote config: \$CONFIG_PATH"

if [[ ! -d "\$INSTALL_DIR/.git" ]]; then
  mkdir -p "\${INSTALL_DIR%/*}"
  echo "Cloning macbook-setup into \$INSTALL_DIR ..."
  git clone "\$REPO_URL" "\$INSTALL_DIR"
else
  echo "Updating macbook-setup in \$INSTALL_DIR ..."
  git -C "\$INSTALL_DIR" pull --ff-only || true
fi

cp "\$CONFIG_PATH" "\$INSTALL_DIR/machine.json"
cd "\$INSTALL_DIR"
exec bash ./scripts/apply-config.sh ./machine.json
`;
}

/**
 * @param {object} config
 */
export function generateConfigJson(config) {
  const payload = {
    ...config,
    version: config.version ?? CATALOG_VERSION,
    generatedAt: new Date().toISOString(),
  };
  return JSON.stringify(payload, null, 2);
}

/**
 * Build a Brewfile snippet from selected app ids (for preview / docs).
 * @param {string[]} appIds
 */
export function brewfilePreview(appIds) {
  const selected = APPS.filter((a) => appIds.includes(a.id));
  const taps = [...new Set(selected.map((a) => a.tap).filter(Boolean))];
  const lines = [];
  for (const tap of taps) lines.push(`tap "${tap}"`);
  if (taps.length) lines.push("");
  for (const app of selected) {
    if (app.brew) lines.push(`brew "${app.brew}"`);
    if (app.cask) lines.push(`cask "${app.cask}"`);
  }
  return lines.join("\n") || "# (no packages selected)";
}

/**
 * @param {string} text
 * @param {string} filename
 * @param {string} mime
 */
export function downloadText(text, filename, mime = "text/plain") {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * @param {string} text
 */
export async function copyText(text) {
  await navigator.clipboard.writeText(text);
}
